import javax.swing.*;import java.awt.*;import java.util.*;
public class LibrarySearch extends JFrame{JTextField search=new JTextField(20);JComboBox<String>cat=new JComboBox<>(new String[]{"All","Java","AI","Networks"});DefaultListModel<String>model=new DefaultListModel<>();JList<String>results=new JList<>(model);JLabel status=new JLabel("Ready");java.util.List<String>books=Arrays.asList("Java: Effective Java","Java: Programming in Java","AI: Artificial Intelligence","AI: Machine Learning Basics","Networks: Mobile Computing","Networks: Computer Networks");
LibrarySearch(){super("CAMPUS LIBRARY CATALOGUE");setLayout(new BorderLayout());JPanel title=new JPanel(new FlowLayout(FlowLayout.CENTER));title.add(new JLabel("CAMPUS LIBRARY CATALOGUE"));add(title,BorderLayout.NORTH);JPanel centre=new JPanel(new BorderLayout());JPanel row=new JPanel(new FlowLayout(FlowLayout.LEFT));row.add(new JLabel("Search"));row.add(search);row.add(cat);JButton find=new JButton("Search");row.add(find);centre.add(row,BorderLayout.NORTH);centre.add(new JScrollPane(results),BorderLayout.CENTER);add(centre);JPanel south=new JPanel(new BorderLayout());JPanel buttons=new JPanel();for(String s:new String[]{"Prev","Next","Reserve"}){JButton b=new JButton(s);buttons.add(b);b.addActionListener(e->status.setText(s.equals("Reserve")?(results.getSelectedValue()==null?"Select a book":"Reserved "+results.getSelectedValue()):s+" page"));}south.add(buttons);south.add(status,BorderLayout.SOUTH);add(south,BorderLayout.SOUTH);find.addActionListener(e->runSearch());search.addActionListener(e->runSearch());cat.addActionListener(e->runSearch());setSize(820,500);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);runSearch();}
void runSearch(){model.clear();String q=search.getText().toLowerCase(),c=(String)cat.getSelectedItem();for(String b:books)if((c.equals("All")||b.startsWith(c+":"))&&b.toLowerCase().contains(q))model.addElement(b);status.setText(model.size()+" result(s)");}public static void main(String[]a){SwingUtilities.invokeLater(()->new LibrarySearch().setVisible(true));}}
